export const BODY: string = "\n<p>الصورة التي أُزيلت خلفيتها تبقى ناقصة. القصاصة الشفافة تحتاج إلى شيء خلفها قبل استخدامها، والصورة البسيطة تحتاج أحيانًا إلى إطار يناسب المكان الذي ستُنشر فيه.</p>\n<p>أداة <a href=\"/ar/idafa-khalfiyya-ila-as-sura/\">إضافة خلفية إلى الصورة</a> تضع أي صورة أو قصاصة PNG شفافة فوق لون واحد أو تدرج من لونين أو نسخة مموّهة من نفسها. تعمل بالكامل في متصفحك، فتبقى صورك خاصة.</p>\n<p>يشرح هذا الدليل أوضاع الخلفية الثلاثة وأدوات التأطير وخيارات التصدير، ويوضح متى يناسب كل خيار. سواء كنت تبيع منتجات أو تنشر على وسائل التواصل أو تصمم شعارات، ستجد هنا ما تحتاجه.</p>\n<h2 id=\"what-adding-a-background-means\">ماذا يعني إضافة خلفية؟</h2>\n<p>إضافة خلفية تعني وضع صورة رئيسية فوق خلفية جديدة. قد تكون الصورة الرئيسية قصاصة PNG شفافة أو صورة منتج أو شعارًا أو لقطة شاشة، والخلفية الجديدة هي المشهد الذي تستقر فيه.</p>\n<p>النتيجة صورة واحدة مكتملة تجمع الصورة الرئيسية والخلفية معًا. يمكنك حفظها بصيغة JPG أو PNG واستخدامها في أي مكان تعمل فيه الصور العادية، مثل إعلان متجر أو منشور اجتماعي.</p>\n<h2 id=\"the-three-background-modes\">أوضاع الخلفية الثلاثة</h2>\n<p>وضع اللون الواحد يملأ اللوحة بلون واحد مسطح. إنه الخيار الأنظف لصور المنتجات والشعارات ولقطات التطبيقات، لأن لا شيء ينافس الصورة الرئيسية على الانتباه.</p>\n<p>وضع التدرج يمزج لونين عبر اللوحة بزاوية تختارها، فيضيف عمقًا دون فوضى. أما وضع الصورة المموّهة فيملأ اللوحة بنسخة مموّهة من الصورة الرئيسية نفسها، وهو الحل الكلاسيكي عندما لا تطابق الصورة شكل الإطار.</p>\n<h2 id=\"solid-color-backgrounds\">خلفيات اللون الواحد</h2>\n<p>الخلفية الواحدة هي الخيار الآمن عندما يجب أن تكون الصورة الرئيسية هي الشيء الوحيد الذي تلاحظه العين. إعلانات المنتجات وصور الملف الشخصي وقوالب الشعارات تستفيد من خلفية هادئة لا تشتت الانتباه.</p>\n<p>الأبيض هو الافتراضي للتجارة الإلكترونية لأن المتاجر تتوقعه ولأنه يجعل المنتجات تبدو نظيفة وصادقة. أما ألوان العلامة التجارية فتناسب الحملات، والخلفيات الداكنة تناسب المنتجات الفاخرة والصور الدرامية.</p>\n<h2 id=\"gradient-backgrounds\">الخلفيات المتدرجة</h2>\n<p>التدرج ينتقل من لون إلى آخر عبر اللوحة، ويحدد التحكم في الزاوية اتجاه المزج. التدرج القطري يبدو ديناميكيًا، والعمودي يبدو هادئًا، والأفقي يبدو متوازنًا.</p>\n<p>تعمل التدرجات بأفضل شكل عندما يكون اللونان قريبين، مثل أزرقين أو أزرق وأخضر مزرق. الرسوم الاجتماعية هي الموطن الطبيعي للتدرجات، لكن حافظ على التدرج خفيفًا عندما تحمل الصورة الرئيسية تفاصيل كثيرة.</p>\n<h2 id=\"blurred-photo-backgrounds\">خلفيات الصور المموّهة</h2>\n<p>وضع الصورة المموّهة يحل مشكلة النسبة. الصورة العمودية المنشورة كمربع تترك فراغات فارغة على الجانبين، والصورة الأفقية المنشورة كقصة تترك فراغات في الأعلى والأسفل، والنسخة المموّهة تملأ هذه الفراغات.</p>\n<p>يحدد التحكم في نصف قطر التمويه مدى نعومة الخلفية. التمويه الخفيف يبقي أشكال الأصل ظاهرة ويناسب صور السفر، والتمويه القوي يخفي التفاصيل. كما يضيف الوضع لونًا خفيفًا يساعد الصورة الواضحة على البروز.</p>\n<h2 id=\"canvas-aspect-ratios\">نسب أبعاد اللوحة</h2>\n<p>نسبة اللوحة تحدد الشكل النهائي للصورة. توفر الأداة إعدادات مسبقة للأشكال الشائعة: مربع للخلاصات والإعلانات، و16:9 للشاشات العريضة، و4:5 لمنشورات وسائل التواصل.</p>\n<p>المربع هو الشكل الأكثر تنوعًا لأنه يعمل في الخلاصات والإعلانات والصور المصغرة. أما الشكل العريض 16:9 فيناسب اللافتات وصور الفيديو المصغرة، والشكل العمودي 4:5 يناسب الخلاصات التي تكافئ الصور الطويلة.</p>\n<h2 id=\"image-scale-and-margins\">حجم الصورة والهوامش</h2>\n<p>مقياس الصورة يتحكم في حجم ظهور الصورة الرئيسية داخل اللوحة. المقياس الكبير يملأ الإطار ويجعل المنتج بطل الصورة، والمقياس الصغير يترك هوامش واسعة ويعطي إحساسًا بالهدوء.</p>\n<p>الهوامش مهمة لأن الصورة الملتصقة بالحافة تبدو ضيقة، بينما الصورة الطافية في بحر من الخلفية تبدو ضائعة. راجع النتيجة بالحجم الذي ستُعرض به، لأن الهوامش الواسعة على الشاشة الكاملة تبدو فارغة في الصورة المصغرة.</p>\n<h2 id=\"roundness-and-drop-shadow\">تدوير الزوايا والظل</h2>\n<p>التدوير ينعّم زوايا الصورة الرئيسية. في الصورة المستطيلة، الزوايا المدورة تعطي إحساسًا بالبطاقة ويناسب منشورات التواصل ولقطات التطبيقات. أما القصاصات الشفافة فتستفيد أكثر من الظل.</p>\n<p>الظل يجعل الصورة الرئيسية ترتفع عن الخلفية ويضيف عمقًا، فيجعل القصاصة تبدو موضوعة لا ملصقة. كلا التحكمين خفيف بطبيعته: ظل قوي أو نصف قطر مبالغ فيه يجذب الانتباه إلى التأثير بدل الصورة.</p>\n<h2 id=\"output-formats-and-quality\">صيغ الإخراج والجودة</h2>\n<p>تصدّر الأداة الصورة المكتملة بصيغة JPG أو PNG. اختر JPG للصور ولأي صورة يهم فيها حجم الملف الصغير، مثل لافتة موقع أو منشور اجتماعي.</p>\n<p>اختر PNG عندما تحمل الصورة نصًا حادًا وألوانًا مسطحة قد يطمسها JPG. جودة تصدير JPG عالية افتراضيًا، وهذا يحافظ على تفاصيل الصورة الرئيسية ونعومة التدرج، لأن التدرج بجودة منخفضة يظهر خطوطًا واضحة.</p>\n<h2 id=\"backgrounds-for-product-photos\">خلفيات صور المنتجات</h2>\n<p>صور المنتجات تعيش أو تموت بخلفيتها. الخلفية البيضاء النظيفة هي معيار المتاجر لأنها تزيل التشتيت وتتيح للمشترين مقارنة المنتجات على قدم المساواة.</p>\n<p>ألوان العلامة التجارية تناسب المتاجر الخاصة والمتاجر الاجتماعية، حيث الصورة إعلان بقدر ما هي قائمة عرض. ومهما اخترت، حافظ على الاتساق في كل تشكيلة المنتجات، لأن متجرًا بخلفيات مختلفة يبدو غير منظم.</p>\n<h2 id=\"backgrounds-for-social-media\">خلفيات وسائل التواصل الاجتماعي</h2>\n<p>خلاصات التواصل تكافئ الصور التي توقف التمرير، والخلفية تقوم بنصف هذا العمل. التدرج القوي أو لون العلامة البارز يجذب الانتباه أسرع من المربع الأبيض العادي.</p>\n<p>طابق شكل اللوحة مع المنصة: مربع لشبكة الخلاصة، وعمودي 4:5 للتمرير، وعريض 16:9 لروابط القصص. واترك مساحة لواجهة المنصة، لأن النصوص والأزرار تتداخل مع حواف الصورة في معظم التطبيقات.</p>\n<h2 id=\"common-mistakes\">الأخطاء الشائعة</h2>\n<p>الخطأ الأكثر شيوعًا هو خلفية تنافس الصورة الرئيسية. التدرج القوي خلف منتج مفصل، أو الخلفية المموّهة المزدحمة خلف شعار رفيع، يقسّم الانتباه ويضعف الصورة.</p>\n<p>من الأخطاء الأخرى نسيان صيغة التصدير وتجاهل حجم العرض النهائي. وأخيرًا، كثيرون يضيفون خلفية إلى صورة ما زالت تحمل خلفيتها الأصلية الفوضوية، فتبقى الخلفية القديمة ظاهرة داخل الإطار الجديد.</p>\n<h2 id=\"quick-reference\">مرجع سريع: كيف تختار خلفية</h2>\n<p>استخدم لونًا واحدًا للإعلانات والشعارات وكل ما يتطلب أن تهيمن الصورة الرئيسية. واستخدم التدرج للرسوم الاجتماعية والعروض حيث تساعد الطاقة. واستخدم الصورة المموّهة عندما لا تطابق الصورة شكل الإطار.</p>\n<p>اضبط نسبة اللوحة حسب الوجهة، وامنح الصورة الرئيسية مساحة للتنفس، وصدّر JPG للصور وPNG للنص الحاد. وللخطوات التفصيلية، اقرأ <a href=\"/ar/blog/kayfiyya-idafa-khalfiyya-ila-as-sura/\">كيف تضيف خلفية إلى صورة</a>، ولنصائح المنتجات اقرأ <a href=\"/ar/blog/khalfiyyat-suwar-al-muntajat/\">خلفيات صور المنتجات: الألوان والسياق</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما الفرق بين إضافة خلفية وإزالة خلفية؟","answer":"إزالة الخلفية تحذف الخلفية القديمة وتترك قصاصة شفافة. إضافة الخلفية تضع تلك القصاصة، أو أي صورة، فوق خلفية جديدة مثل لون واحد أو تدرج أو صورة مموّهة. الخطوتان تعملان معًا غالبًا."},{"question":"ما وضع الخلفية الذي أختاره لصورة منتج؟","answer":"الخلفية البيضاء الواحدة هي المعيار في المتاجر لأنها تُبقي المنتج البطل الوحيد. لون العلامة يناسب متجرك الخاص أو خلاصتك الاجتماعية، والخلفية المموّهة تناسب صور نمط الحياة."},{"question":"هل يمكنني إضافة خلفية إلى صورة ما زالت تحمل خلفيتها الأصلية؟","answer":"نعم، الأداة تضع الصورة كاملة فوق الخلفية الجديدة، لكن الخلفية الأصلية تبقى ظاهرة داخل الإطار. للحصول على نتيجة نظيفة، أزل الخلفية القديمة أولًا ثم أضف الجديدة."},{"question":"هل أصدّر بصيغة JPG أم PNG بعد إضافة الخلفية؟","answer":"استخدم JPG للصور ولأي صورة يهم فيها حجم الملف الصغير، مثل منشورات التواصل ولافتات المواقع. واستخدم PNG عندما تحمل الصورة نصًا حادًا أو ألوانًا مسطحة تحتاج إلى حواف واضحة."},{"question":"لماذا يظهر تدرجي خطوطًا واضحة؟","answer":"تظهر الخطوط عندما يُحفظ التدرج الناعم بجودة منخفضة، لأن ضغط JPG يجمع الدرجات المتقاربة في خطوات ظاهرة. صدّر بجودة عالية للحفاظ على التدرج ناعمًا، وفضّل PNG للتدرجات الحساسة."},{"question":"هل إضافة خلفية تغيّر ملف صورتي الأصلي؟","answer":"لا، الأداة تنشئ صورة جديدة تجمع الصورة الرئيسية والخلفية، ويبقى ملفك الأصلي سليمًا على جهازك. يمكنك تصدير عدة نسخ بخلفيات مختلفة من نفس المصدر."}];
